const body = $json.body ?? $json;
if (!/^release-[a-zA-Z0-9.-]+$/.test(body.release_id ?? '')) throw new Error('Invalid release_id');
if (body.environment !== 'staging') throw new Error('Only staging is supported');
return [{json: {release_id: body.release_id, environment: body.environment, execution_id: $execution.id}}];

const context = $('Start check').first().json;
const mapping = {
  Release_MCP_get_release: ['release-mcp', 'get_release', 'release'],
  Release_MCP_get_checks: ['release-mcp', 'get_checks', 'checks'],
  Ops_MCP_get_environment: ['ops-mcp', 'get_environment', 'environment'],
  Ops_MCP_get_runbook: ['ops-mcp', 'get_runbook', 'runbook'],
};
// n8n serializes MCP observations as JSON; unwrap content blocks, not AI prose.
function records(value) {
  if (typeof value === 'string') { try { return records(JSON.parse(value)); } catch { return []; } }
  if (Array.isArray(value)) return value.flatMap(records);
  if (!value || typeof value !== 'object') return [];
  if (value.isError === true) throw new Error('MCP returned an error');
  return [value, ...Object.values(value).flatMap(records)];
}
const evidence = {}, tool_calls = [];
for (const step of $json.intermediateSteps ?? []) {
  const spec = mapping[step.action?.tool];
  if (!spec) throw new Error('Unknown tool: ' + step.action?.tool);
  const [server, tool, key] = spec;
  if (evidence[key]) throw new Error('Duplicate tool call: ' + tool);
  const candidates = records(step.observation).filter(r =>
    key === 'release' ? typeof r.image_digest === 'string' && r.release_id :
    key === 'checks' ? Array.isArray(r.checks) && r.release_id :
    key === 'environment' ? typeof r.free_capacity_percent === 'number' && r.environment :
    Array.isArray(r.rollback_steps) && r.service);
  if (!candidates.length) throw new Error('Missing evidence from ' + tool);
  const result = candidates[0];
  evidence[key] = result;
  const {tool: dispatchTool, ...args} = step.action.toolInput;
  if (dispatchTool !== undefined && dispatchTool !== step.action.tool) throw new Error('Tool dispatch mismatch');
  tool_calls.push({server, tool, arguments:args, result});
}
if (tool_calls.length !== 4) throw new Error('Expected four MCP tool calls, got ' + tool_calls.length);
return [{json:{release_id:context.release_id,environment:context.environment,execution_id:context.execution_id,
  model:context.model,summary:$json.output,evidence,tool_calls}}];

const result = $json;
const e = result.evidence;
if (!e?.release || !e?.checks || !e?.environment || !e?.runbook) throw new Error('Incomplete evidence');
if (e.release.release_id !== result.release_id || e.checks.release_id !== result.release_id || e.environment.environment !== result.environment || e.runbook.service !== e.release.service) throw new Error('Evidence scope mismatch');
const required = e.checks.checks.filter(c => c.required === true);
if (!required.length) throw new Error('No required checks in evidence');
const reasons = [];
for (const c of required) if (c.status !== 'passed') reasons.push('Required check failed: ' + c.name);
if (e.release.image_signed !== true) reasons.push('Image is not signed');
if (e.release.digest_pinned !== true) reasons.push('Image digest is not pinned');
if (!/^sha256:[a-f0-9]{64}$/.test(e.release.image_digest ?? '')) reasons.push('Image digest is invalid');
if (e.release.rollback_ready !== true || e.runbook.rollback_supported !== true || !e.runbook.rollback_steps?.length) reasons.push('Rollback is not ready');
if (e.environment.status !== 'healthy' || e.environment.shop_api_healthy !== true) reasons.push('Environment is unhealthy');
if (typeof e.environment.free_capacity_percent !== 'number' || e.environment.free_capacity_percent < 30) reasons.push('Free capacity below 30%');
return [{json: {...result, execution_id: $execution.id, decision: reasons.length ? 'blocked' : 'approved', reasons}}];
